import ast, os, json

KEY = "DB_URL"
results = {}

def is_environ(node):
    # os.environ, environ, os.environb
    if isinstance(node, ast.Attribute) and node.attr == "environ":
        return True
    if isinstance(node, ast.Name) and node.id in ("environ",):
        return True
    return False

def func_name(call):
    f = call.func
    if isinstance(f, ast.Attribute):
        base = f.value
        if isinstance(base, ast.Name):
            return base.id + "." + f.attr
        if isinstance(base, ast.Attribute):
            return base.attr + "." + f.attr
        return f.attr
    if isinstance(f, ast.Name):
        return f.id
    return None

READ_CALLS = {"os.getenv", "getenv", "os.environ.get", "environ.get",
              "os.environ.setdefault", "environ.setdefault", "os.getenvb", "getenvb"}

for root, dirs, files in os.walk("."):
    for fn in sorted(files):
        p = os.path.join(root, fn)
        rel = os.path.relpath(p, ".")
        src = open(p, encoding="utf-8").read()
        if KEY not in src:
            continue
        tree = ast.parse(src)
        findings = []
        for node in ast.walk(tree):
            # subscript read: os.environ["DB_URL"]
            if isinstance(node, ast.Subscript):
                sl = node.slice
                if isinstance(sl, ast.Constant) and sl.value == KEY:
                    ctx = type(node.ctx).__name__
                    findings.append(("subscript", ctx, is_environ(node.value), node.lineno))
            # calls
            if isinstance(node, ast.Call):
                name = func_name(node)
                args = node.args
                keys = []
                for a in args:
                    if isinstance(a, ast.Constant) and isinstance(a.value, str):
                        keys.append(a.value)
                for kw in node.keywords:
                    if kw.arg == "key" and isinstance(kw.value, ast.Constant):
                        keys.append(kw.value.value)
                for k in keys:
                    if k == KEY:
                        findings.append(("call", name, node.lineno))
                    elif KEY in k:
                        findings.append(("call-substr", name, k, node.lineno))
            # string constants exactly DB_URL outside of those handled
            if isinstance(node, ast.Constant) and isinstance(node.value, str) and KEY in node.value:
                findings.append(("strconst", node.value, node.lineno))
        results[rel] = findings

for rel, f in results.items():
    print(rel)
    for x in f:
        print("   ", x)
